(() => {
  // E2E only: publishes a small open-land revision through window.seed.cartridges.publish (the IPC
  // Create's Build ends with), as run-a1-base-commercial-off.json does, with a look.png that is
  // empty, not a picture, cut off, or whole, so main's publish-time picture check decides.
  const bytesOf = (b64) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  const png = bytesOf("iVBORw0KGgoAAAANSUhEUgAAAEAAAABACAIAAAAlC+aJAAAAeklEQVR4nO3PUQkAIBTAwBfVKEYxqiH8OITBAtxm7fN1wwUNaEEDWtCAFjSgBQ1oQQNa0IAWNKAFDWhBA1rQgBY0oAUNaEEDWtCAFjSgBQ1oQQNa0IAWNKAFDWhBA1rQgBY0oAUNaEEDWtCAFjSgBQ1oQQNa0IAWPHYBHwIBadNjfowAAAAASUVORK5CYII=");
  const pictures = {
    empty: new Uint8Array(0),
    text: new TextEncoder().encode("not a picture"),
    cut: png.slice(0, Math.floor(png.length / 2)),
    whole: png,
  };
  window.__pub = async (version, picture) => {
    const { openLandCartridge } = await import("/narrative/openLandCartridge.ts");
    const base = await window.seed.cartridges.read("aether-land", "1.3.0");
    if (!base.ok) return base;
    const input = await openLandCartridge({
      cartridgeId: "e2e-picture", version, name: "E2E picture check", author: "e2e",
      premise: "A revision made to exercise the publish-time picture check.",
      originSource: base.value.scenes.origin, bible: base.value.bible,
      createdAt: new Date().toISOString(), look: pictures[picture],
    });
    if (!input.ok) return input;
    const published = await window.seed.cartridges.publish(input.value);
    if (!published.ok) return { version, picture, bytes: pictures[picture].length, refused: published.error };
    const rev = await window.seed.cartridges.read("e2e-picture", version);
    return { version, picture, bytes: pictures[picture].length, published: published.value.contentHash, lookBytes: rev.ok ? rev.value.assets["look.png"].length : null };
  };
  return "defined";
})()

(async () => {
  // A sketch this app draws through the gateway now (drawLook, the look step's own IPC, on the
  // draft of run-fix-look-ids; fixture mode `usage`): a real 512 x 512 PNG main wrote must pass the
  // same check, as a lineage revision of 1.0.0.
  const drawn = await window.seed.createDrafts.drawLook("75769d0f16ddb7b0", 0, crypto.randomUUID());
  if (!drawn.ok) return drawn;
  const looks = await window.seed.createDrafts.looks("75769d0f16ddb7b0");
  const look = looks.value.find((l) => l.id === drawn.value.id) ?? looks.value[0];
  const url = look.dataUrl ?? look.url;
  const bytes = Uint8Array.from(atob(url.slice(url.indexOf(",") + 1)), (c) => c.charCodeAt(0));
  const { openLandCartridge } = await import("/narrative/openLandCartridge.ts");
  const base = await window.seed.cartridges.read("aether-land", "1.3.0");
  const input = await openLandCartridge({
    cartridgeId: "e2e-picture", version: "1.0.1", name: "E2E picture check", author: "e2e",
    premise: "A revision made to exercise the publish-time picture check.",
    originSource: base.value.scenes.origin, bible: base.value.bible,
    createdAt: new Date().toISOString(), look: bytes,
  });
  const parent = (await window.seed.cartridges.list()).value.find((m) => m.cartridgeId === "e2e-picture" && m.version === "1.0.0");
  const lineage = { kind: "revision", parent: { cartridgeId: parent.cartridgeId, version: parent.version, contentHash: parent.contentHash } };
  const published = await window.seed.cartridges.publish({ ...input.value, manifest: { ...input.value.manifest, lineage } });
  return published.ok ? { version: "1.0.1", look: drawn.value.id, bytes: bytes.length, published: published.value.contentHash } : published;
})()
